def curves(stock,src,url,edition,file,extra=''):
    d=dg[stock]; c=d['channels']
    val={'rms_at_net_density_1.0_per_record':{k:c[k]['rms_at_netD1'] for k in 'RGB'},
         'reading_spread_pm1pt':{k:c[k]['rms_pm1pt'] for k in 'RGB'},
         'rms_at_exposure_where_green_net_D_is_1.0':{k:d['at_green_netD1_exposure'][k] for k in 'RGB'},
         'rms_range_midscale_30_to_80pct_of_log_exposure_axis':{k:c[k]['rms_range_midscale'] for k in 'RGB'},
         'dmin_read':{k:c[k]['dmin'] for k in 'RGB'}}
    return dict(stock=stock,kind='curves',values=val,
      conditions="Diffuse rms granularity curves per colour record (R,G,B Status M densities), microdensitometer, 48 um aperture, Process ECN-2. No single visual-density figure is published.",
      source=src,url=url,edition=edition,tag='SHEET (curve digitised from the PDF vector paths; reading is mine)',file=file,
      notes=("Read per the sheet's own rule: density on the record's characteristic curve -> same log exposure on that record's granularity curve -> sigma_D x 1000. "
             "Target density = that record's D-min (left end of plotted curve) + 1.0. Axis fit from the sheet's own tick marks (log sigma axis residual <= 0.25 pt). "
             "Uncertainty: about +/-4% from line width (+/-1 pt), +/-3% from a +/-0.05 D target shift; Kodak's own note says the granularity and sensitometric curves come from different equipment "
             "('a slight variation in curve shape may be noticed'), so treat as +/-10%. "+extra))
