meta={'generated':'2026-10-07','rule':'Every value was read in a fetched document saved under sheets/. Nothing from memory.',
 'pgi_to_rms':{'published_conversion':None,
  'finding':"Kodak E-58 'Print Grain Index' (July 2000, minor revision 7-00; file kodak_E-58_print_grain_index_2000-07.pdf) gives NO PGI-to-rms conversion and says the scale 'cannot be compared with rms granularity'. It names three steps (RGB negative granularity -> RGB print granularity -> visual granularity -> perceived graininess) and states 'We will not describe the mathematical details'. Its only quantitative statements: film-to-print granularity is linear for most films; perceived graininess intervals 'correlate well with the logarithm of the visual granularity'; 25 = threshold; 2 units = 50% JND, 4 units = 90% JND.",
  'ASSUMED_relative_mapping':{'label':'ASSUMED - not published, relative only, do not use as sheet data',
   'basis':"PGI is stated to be linear in log(visual granularity). In every PGI table read here, doubling magnification 4.4X->8.8X adds 21-22 units and 8.8X->17.8X adds 29-30. IF print granularity at the fixed 14 in viewing distance scaled in proportion to magnification, that is 73 to 97 PGI units per decade of granularity, so a PGI difference d between two films at the same magnification would be an rms ratio of 10^(d/73) to 10^(d/97). The two steps disagree, which shows the proportionality does not hold exactly (eye/system MTF enters).",
   'ratios_vs_portra_160_from_135_values':{'kodak_portra_400 (d=+9)':[1.24,1.33],'kodak_portra_800 (d=+20)':[1.61,1.88],'kodak_gold_200 (d=+16)':[1.46,1.66],'kodak_ultramax_400 (d=+18)':[1.53,1.76],'kodak_ektar_100 (d=-12, from the 8.8X row)':[0.69,0.75]}},
  'absolute_anchor_tested_and_rejected':"Only sheets found carrying BOTH figures: KODAK PROFESSIONAL PORTRA 400BW (F-4012, July 2003: RMS 9 at net diffuse visual density 1.00, 48 um; PGI 135 <25 / 40 / 70) and T400 CN (F-2350, Feb 1999: RMS 9). These are chromogenic B&W films. Using 'PGI 40 at 8.8X = rms 9' as an anchor would put Portra 160 near 12 and Portra 400 near 16, i.e. Portra 400 as grainy as TRI-X (17) and twice the Vision3 500T green record (7.1). That is not credible, so no absolute PGI->rms mapping is offered."},
 'rows':rows}
json.dump(meta,open(G+'/published_granularity.json','w'),indent=1,ensure_ascii=False)
with open(G+'/published_granularity.csv','w',newline='') as f:
    w=csv.writer(f); w.writerow(['stock','kind','values','conditions','source','url','edition','tag','notes','predecessor_or_older_edition','file'])
    for r in rows:
        w.writerow([r['stock'],r['kind'],json.dumps(r['values'],ensure_ascii=False),r['conditions'],r['source'],r['url'],r['edition'],r['tag'],r['notes'],json.dumps(r.get('predecessor_or_older_edition',[]),ensure_ascii=False),r['file']])
print(len(rows),'rows')
for r in rows:
    assert r['file'].startswith('(repo)') or os.path.exists(H+'/../'+r['file']),r['file']
    for p in r.get('predecessor_or_older_edition',[]): assert os.path.exists(H+'/../'+p['file']),p['file']
